    out = [row[:] for row in grid]

    # Identify zero regions, then fill regions enclosed by the 5-pattern.
    seen = set()
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            regions.append(comp)

    for comp in regions:
        # A pocket is bordered by 5s on at least three sides; edge-touching
        # pockets can still be enclosed when the 5-pattern caps the opening.
        rmin = min(r for r, c in comp)
        rmax = max(r for r, c in comp)
        cmin = min(c for r, c in comp)
        cmax = max(c for r, c in comp)
        border_sides = set()
        for r, c in comp:
            for dr, dc, name in ((1, 0, "bottom"), (-1, 0, "top"),
                                 (0, 1, "right"), (0, -1, "left")):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5:
                    border_sides.add(name)

        edge_sides = set()
        if rmin == 0: edge_sides.add("top")
        if rmax == h - 1: edge_sides.add("bottom")
        if cmin == 0: edge_sides.add("left")
        if cmax == w - 1: edge_sides.add("right")

